Looking at this problem, I need to:

1. Load the graph from graph.json
2. Find the shortest path from svc-928 to db-877 in terms of the number of "dependsOn" edges
3. Return the count of "dependsOn" edges on that path

Let me write a solution using BFS to find the shortest path considering only "dependsOn" edges:

```python
import json
from collections import deque

# Load the graph
with open('graph.json', 'r') as f:
    graph_data = json.load(f)

# Build adjacency list for dependsOn edges
depends_on_graph = {}
for node in graph_data['nodes']:
    depends_on_graph[node['id']] = []

for edge in graph_data['edges']:
    source, relation, target = edge
    if relation == 'dependsOn':
        depends_on_graph[source].append(target)

# BFS to find shortest path from svc-928 to db-877
def bfs_shortest_path(start, end, graph):
    if start not in graph or end not in graph:
        return None

    queue = deque([(start, 0)])  # (node, distance)
    visited = {start}

    while queue:
        node, dist = queue.popleft()

        if node == end:
            return dist

        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))

    return None

# Find the minimum number of dependsOn edges
result = bfs_shortest_path('svc-928', 'db-877', depends_on_graph)

if result is None:
    # No path found
    answer = -1  # or could indicate no path exists
else:
    answer = result

print(json.dumps({"answer_type": "number", "answer": answer}))
```

